using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;

namespace FileCompass {
 internal sealed class TagPickerWindow : Window {
  internal readonly TabControl Tabs=new TabControl{Margin=new Thickness(12,8,12,0)};
  internal readonly TextBox SearchInput=new TextBox{MinHeight=30,Margin=new Thickness(0,0,0,10)};
  internal readonly TextBox AssignInput=new TextBox{MinHeight=30,Margin=new Thickness(0,4,0,4)};
  internal readonly RadioButton[] ModeButtons=new RadioButton[3];
  internal readonly Button SearchButton,SaveButton;
  internal readonly string[] Paths;
  internal string Query; internal bool Exact,Assign; internal string[] Labels; internal int ChangeMode; internal IDictionary<string,string> Colors;
  internal Task LoadingTask;
  readonly WrapPanel searchChoices=new WrapPanel(),assignChoices=new WrapPanel();
  readonly ComboBox labelChoice=new ComboBox{Margin=new Thickness(0,0,8,0)},colorChoice=new ComboBox();
  readonly Dictionary<string,string> changedColors=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);
  readonly Dictionary<string,Border> swatches=new Dictionary<string,Border>(StringComparer.OrdinalIgnoreCase);
  Dictionary<string,string> savedColors=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);bool updatingColor,closed;
  internal TagPickerWindow(Window owner,Entry[] selected,bool validSelection){
   Paths=validSelection?selected.Select(x=>x.FullPath).ToArray():new string[0];string title=L.Text("tags.workspace");CopyUi.Style(this,owner,title,660);MaxHeight=SystemParameters.WorkArea.Height;var root=SettingsUx.Frame(this,title,out var actions);root.Children.Add(Tabs);
   var searchBody=new DockPanel{Margin=new Thickness(16,10,16,12)};var prompt=CopyUi.Label(L.Text("tags.globalPrompt"));DockPanel.SetDock(prompt,Dock.Top);searchBody.Children.Add(prompt);System.Windows.Automation.AutomationProperties.SetLabeledBy(SearchInput,prompt);DockPanel.SetDock(SearchInput,Dock.Top);searchBody.Children.Add(SearchInput);searchBody.Children.Add(new ScrollViewer{Content=searchChoices,MinHeight=110,MaxHeight=220,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
   var searchTab=new TabItem{Header=L.Text("action.search"),Content=searchBody};
   var assignBody=new StackPanel{Margin=new Thickness(8,10,8,12)};var assignTab=new TabItem{Header=L.Text("tags.actionAdd"),Content=assignBody};Tabs.Items.Add(assignTab);Tabs.Items.Add(searchTab);
   assignBody.Children.Add(CopyUi.Label(validSelection?L.Format("tags.selectionCount",Paths.Length):L.Text("tags.localSelectionRequired")));
   var controls=new StackPanel{IsEnabled=validSelection};assignBody.Children.Add(controls);if(validSelection&&selected.Length==1)AssignInput.Text=String.Join("; ",selected[0].TagNames??new string[0]);controls.Children.Add(AssignInput);controls.Children.Add(CopyUi.Label(L.Text("tags.inputHelp")));
   var modeRow=new WrapPanel{Margin=new Thickness(0,6,0,0)};controls.Children.Add(modeRow);var modeHelp=new TextBlock{Foreground=FluentTheme.Muted,TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,2,0,5)};var modeNames=new[]{"tags.actionAdd","tags.actionReplace","tags.actionRemove"};var descriptions=new[]{"tags.add","tags.replace","tags.remove"};for(int i=0;i<ModeButtons.Length;i++){int index=i;var radio=new RadioButton{Content=L.Text(modeNames[i]),ToolTip=L.Text(descriptions[i]),Margin=new Thickness(0,2,20,2),IsChecked=i==0};radio.Checked+=delegate{modeHelp.Text=L.Text(descriptions[index]);};ModeButtons[i]=radio;modeRow.Children.Add(radio);}modeHelp.Text=L.Text(descriptions[0]);controls.Children.Add(modeHelp);controls.Children.Add(new ScrollViewer{Content=assignChoices,MaxHeight=130,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});
   controls.Children.Add(new TextBlock{Text=L.Text("tags.color"),FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,6,0,2)});var colorRow=new Grid();colorRow.ColumnDefinitions.Add(new ColumnDefinition());colorRow.ColumnDefinitions.Add(new ColumnDefinition());colorRow.Children.Add(labelChoice);Grid.SetColumn(colorChoice,1);colorRow.Children.Add(colorChoice);controls.Children.Add(colorRow);
   System.Windows.Automation.AutomationProperties.SetName(labelChoice,L.Text("tags.colorLabel"));System.Windows.Automation.AutomationProperties.SetName(colorChoice,L.Text("tags.color"));
   foreach(var option in new[]{Tuple.Create("tags.colorAuto",(string)null),Tuple.Create("tags.colorBlue","#326BB1"),Tuple.Create("tags.colorRed","#A83252"),Tuple.Create("tags.colorOrange","#9F560E"),Tuple.Create("tags.colorGreen","#23744D"),Tuple.Create("tags.colorViolet","#754CAB"),Tuple.Create("tags.colorTeal","#287581"),Tuple.Create("tags.colorGray","#57677E"),Tuple.Create("tags.colorBrown","#86602F")})colorChoice.Items.Add(new ComboBoxItem{Content=L.Text(option.Item1),Tag=option.Item2});
   controls.Children.Add(new TextBlock{Text=L.Text("tags.colorHelp"),TextWrapping=TextWrapping.Wrap,Foreground=FluentTheme.Muted,Margin=new Thickness(0,5,0,0)});
   AssignInput.TextChanged+=delegate{UpdateLabels();};labelChoice.SelectionChanged+=delegate{UpdateColor();};colorChoice.SelectionChanged+=delegate{if(updatingColor||!(labelChoice.SelectedItem is string name)||!(colorChoice.SelectedItem is ComboBoxItem option))return;changedColors[name]=option.Tag as string;if(swatches.TryGetValue(name,out var swatch))swatch.Background=new FileTagBadge(name,ColorFor(name)).Color;};UpdateLabels();
   var cancel=CopyUi.Button(L.Text("action.cancel"),()=>DialogResult=false);cancel.IsCancel=true;actions.Children.Add(cancel);
   SearchButton=CopyUi.Button(L.Text("action.search"),delegate{Query=SearchInput.Text.Trim().TrimStart('#');Exact=false;DialogResult=true;});FluentTheme.Primary(SearchButton);actions.Children.Add(SearchButton);
   SaveButton=CopyUi.Button(L.Text("action.save"),delegate{try{Labels=FileTagStore.Normalize(AssignInput.Text);ChangeMode=Array.FindIndex(ModeButtons,x=>x.IsChecked==true);Colors=changedColors.Where(x=>Labels.Contains(x.Key,StringComparer.OrdinalIgnoreCase)).ToDictionary(x=>x.Key,x=>x.Value,StringComparer.OrdinalIgnoreCase);Assign=true;DialogResult=true;}catch(Exception ex){MessageBox.Show(this,ex.Message,L.Text("tags.edit"));}});FluentTheme.Primary(SaveButton);actions.Children.Add(SaveButton);
   Action updateTab=delegate{bool assign=Tabs.SelectedIndex==0;SearchButton.Visibility=assign?Visibility.Collapsed:Visibility.Visible;SaveButton.Visibility=assign?Visibility.Visible:Visibility.Collapsed;SearchButton.IsDefault=!assign;SaveButton.IsDefault=assign;};Tabs.SelectionChanged+=delegate(object sender,SelectionChangedEventArgs e){if(e.Source==Tabs)updateTab();};Tabs.SelectedIndex=validSelection?0:1;updateTab();
   SaveButton.IsEnabled=false;SearchButton.IsEnabled=false;Closed+=delegate{closed=true;};Loaded+=delegate{if(Tabs.SelectedIndex==0)AssignInput.Focus();else SearchInput.Focus();LoadingTask=Load();};
  }
  string ColorFor(string name){return changedColors.TryGetValue(name,out var changed)?changed:savedColors.TryGetValue(name,out var saved)?saved:null;}
  void UpdateLabels(){var previous=labelChoice.SelectedItem as string;string[] names;try{names=FileTagStore.Normalize(AssignInput.Text);}catch(IOException){names=new string[0];}labelChoice.ItemsSource=names;labelChoice.SelectedItem=names.FirstOrDefault(x=>String.Equals(x,previous,StringComparison.OrdinalIgnoreCase))??names.FirstOrDefault();UpdateColor();}
  void UpdateColor(){updatingColor=true;try{string name=labelChoice.SelectedItem as string;labelChoice.IsEnabled=colorChoice.IsEnabled=name!=null;string color=name==null?null:ColorFor(name);colorChoice.SelectedItem=colorChoice.Items.OfType<ComboBoxItem>().FirstOrDefault(x=>String.Equals(x.Tag as string,color,StringComparison.OrdinalIgnoreCase))??colorChoice.Items[0];}finally{updatingColor=false;}}
  async Task Load(){searchChoices.Children.Add(CopyUi.Label(L.Text("state.loading")));assignChoices.Children.Add(CopyUi.Label(L.Text("state.loading")));var snapshot=await Task.Run(()=>{var records=FileTagStore.Current.Snapshot(out var colors,out var known);string error=FileTagStore.LastError;var assigned=new HashSet<string>(records.Where(FileTagStore.MatchesCurrentItem).SelectMany(x=>x.Tags??new string[0]).Select(FileTagStore.DisplayName),StringComparer.OrdinalIgnoreCase);var names=known.Concat(colors.Keys).Concat(records.SelectMany(x=>x.Tags??new string[0])).Where(x=>!String.IsNullOrWhiteSpace(x)).Select(FileTagStore.DisplayName).ToArray();return(Assigned:assigned,Names:names,Colors:colors,Error:error);});if(closed)return;searchChoices.Children.Clear();assignChoices.Children.Clear();if(snapshot.Error!=null){string error=L.Text("tags.loadError")+" "+snapshot.Error;searchChoices.Children.Add(CopyUi.Label(error));assignChoices.Children.Add(CopyUi.Label(error));return;}
   savedColors=snapshot.Colors;SearchButton.IsEnabled=true;SaveButton.IsEnabled=Paths.Length>0;UpdateColor();foreach(string tag in MainWindow.DefaultLabels().Concat(snapshot.Names).Distinct(StringComparer.OrdinalIgnoreCase).OrderByDescending(snapshot.Assigned.Contains).ThenBy(x=>x,StringComparer.CurrentCultureIgnoreCase)){bool assigned=snapshot.Assigned.Contains(tag);var search=TagButton(tag,assigned?snapshot.Colors.TryGetValue(tag,out var color)?color:null:null,assigned);search.IsEnabled=assigned;search.Click+=delegate{Query=tag;Exact=true;DialogResult=true;};searchChoices.Children.Add(search);var add=TagButton(tag,ColorFor(tag),true);add.Click+=delegate{try{AssignInput.Text=String.Join("; ",FileTagStore.Normalize(AssignInput.Text).Concat(new[]{tag}).Distinct(StringComparer.OrdinalIgnoreCase));labelChoice.SelectedItem=labelChoice.Items.Cast<string>().FirstOrDefault(x=>String.Equals(x,tag,StringComparison.OrdinalIgnoreCase));}catch(IOException ex){MessageBox.Show(this,ex.Message,L.Text("tags.edit"));}};assignChoices.Children.Add(add);var caption=(StackPanel)add.Content;swatches[tag]=(Border)caption.Children[0];}
  }
  static Button TagButton(string tag,string color,bool active){var button=CopyUi.Button(tag,delegate{});System.Windows.Automation.AutomationProperties.SetName(button,tag);var caption=new StackPanel{Orientation=Orientation.Horizontal,Opacity=active?1:.55};caption.Children.Add(MainWindow.TagSwatch(active?new FileTagBadge(tag,color).Color:FluentTheme.Muted));caption.Children.Add(new TextBlock{Text=tag,VerticalAlignment=VerticalAlignment.Center,FontWeight=active?FontWeights.SemiBold:FontWeights.Normal});button.Content=caption;return button;}
 }
}
